        res = [0]*(len(A)+len(B)-1)
        for i, a in enumerate(A):
            if not a: continue
            for j, b in enumerate(B):
                if b: res[i+j] = (res[i+j] + a*b) % P
        return res

    def within_poly(sz):
        c = sz*(sz-1)//2
        return [comb(c, k) % P for k in range(c+1)]

    def between_exact_poly(a, b):
        # edges between a-set and b-set, every vertex in b has >= 1 neighbor in a
        total_possible = a * b
        res = [0] * (total_possible + 1)
        for j in range(b+1):
            sign = 1 if j % 2 == 0 else -1
            coef = comb(b, j)
            avail = a * (b - j)
            for m in range(avail+1):
                val = sign * coef * comb(avail, m) % P
                res[m] = (res[m] + val) % P
        return res

    results = [0] * (max_edges + 1)

