class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)

        @lru_cache(maxsize=None)
        def dp(i, has_carry, carry_val):
            # Current window: [carry_val (if has_carry), nums[i], nums[i+1], ...]
            # Build the effective first 3 elements
            window = []
            if has_carry:
                window.append(carry_val)
            j = i
            while len(window) < 3 and j < n:
                window.append(nums[j])
                j += 1

            if len(window) == 0:
                return 0
            if len(window) <= 2:
                return max(window)

            # window has exactly 3 elements
            # j = i + (3 - (1 if has_carry else 0)) = next index after window
            next_base = j  # nums[next_base] is next after window

            best = float('inf')
            # Try all pairs from window[0..2]
