                for b in range(a+1, 3):
                    rem_idx = 3 - a - b  # 0+1+2=3, so rem = 3-a-b
                    cost = max(window[a], window[b])
                    rem_val = window[rem_idx]
                    best = min(best, cost + dp(next_base, True, rem_val))

            return best

        return dp(0, False, 0)
